import React, { useState, useEffect } from "react";
import { useNavigate } from "react-router-dom";
import shippingAPI from "../../services/shippingService";

export default function CreateShipment() {
  const navigate = useNavigate();
  const [formData, setFormData] = useState({
    order_number: "",
    payment_type: "prepaid",
    order_amount: "",
    collectable_amount: "",
    consignee: {
      name: "",
      address: "",
      address_2: "",
      city: "",
      state: "",
      pincode: "",
      phone: ""
    },
    pickup: {
      warehouse_name: "",
      name: "",
      address: "",
      address_2: "",
      city: "",
      state: "",
      pincode: "",
      phone: ""
    },
    products: [{
      product_name: "",
      product_qty: "",
      product_price: ""
    }]
  });

  const [couriers, setCouriers] = useState([]);
  const [selectedCourier, setSelectedCourier] = useState("");
  const [loading, setLoading] = useState(false);

  useEffect(() => {
    getCouriers();
  }, []);

  const getCouriers = async () => {
    try {
      const response = await shippingAPI.getCouriers();
      if (response?.data?.status) {
        setCouriers(response.data.data || []);
      }
    } catch (error) {
      console.error("Error fetching couriers:", error);
    }
  };

  const handleInputChange = (field, value) => {
    setFormData(prev => ({
      ...prev,
      [field]: value
    }));
  };

  const handleConsigneeChange = (field, value) => {
    setFormData(prev => ({
      ...prev,
      consignee: {
        ...prev.consignee,
        [field]: value
      }
    }));
  };

  const handlePickupChange = (field, value) => {
    setFormData(prev => ({
      ...prev,
      pickup: {
        ...prev.pickup,
        [field]: value
      }
    }));
  };

  const handleProductChange = (index, field, value) => {
    const updatedProducts = [...formData.products];
    updatedProducts[index][field] = value;
    setFormData(prev => ({
      ...prev,
      products: updatedProducts
    }));
  };

  const addProduct = () => {
    setFormData(prev => ({
      ...prev,
      products: [...prev.products, { product_name: "", product_qty: "", product_price: "" }]
    }));
  };

  const removeProduct = (index) => {
    if (formData.products.length > 1) {
      const updatedProducts = formData.products.filter((_, i) => i !== index);
      setFormData(prev => ({
        ...prev,
        products: updatedProducts
      }));
    }
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setLoading(true);

    try {
      // Add courier information if selected
      const shipmentData = {
        ...formData,
        courier_id: selectedCourier
      };

      const response = await shippingAPI.createShipment(shipmentData);

      if (response?.data?.status) {
        alert("Shipment created successfully!");
        navigate("/shipping");
      } else {
        alert("Failed to create shipment: " + (response?.data?.message || "Unknown error"));
      }
    } catch (error) {
      console.error("Error creating shipment:", error);
      alert("Error creating shipment: " + (error.response?.data?.message || error.message));
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="create-shipment">
      <div className="create-shipment__header">
        <h3 className="page_heading">Create New Shipment</h3>
        <button
          className="btn btn-secondary"
          onClick={() => navigate("/shipping")}
        >
          Back to Dashboard
        </button>
      </div>

      <form onSubmit={handleSubmit} className="create-shipment__form">
        {/* Basic Order Information */}
        <div className="form-section">
          <h4>Order Information</h4>
          <div className="form-grid">
            <div className="form-group">
              <label>Order Number *</label>
              <input
                type="text"
                value={formData.order_number}
                onChange={(e) => handleInputChange("order_number", e.target.value)}
                required
              />
            </div>
            <div className="form-group">
              <label>Payment Type *</label>
              <select
                value={formData.payment_type}
                onChange={(e) => handleInputChange("payment_type", e.target.value)}
                required
              >
                <option value="prepaid">Prepaid</option>
                <option value="cod">Cash on Delivery</option>
              </select>
            </div>
            <div className="form-group">
              <label>Order Amount *</label>
              <input
                type="number"
                step="0.01"
                value={formData.order_amount}
                onChange={(e) => handleInputChange("order_amount", e.target.value)}
                required
              />
            </div>
            {formData.payment_type === "cod" && (
              <div className="form-group">
                <label>Collectable Amount</label>
                <input
                  type="number"
                  step="0.01"
                  value={formData.collectable_amount}
                  onChange={(e) => handleInputChange("collectable_amount", e.target.value)}
                />
              </div>
            )}
          </div>
        </div>

        {/* Courier Selection */}
        <div className="form-section">
          <h4>Shipping Courier</h4>
          <div className="form-group">
            <label>Select Courier</label>
            <select
              value={selectedCourier}
              onChange={(e) => setSelectedCourier(e.target.value)}
            >
              <option value="">Select Courier</option>
              {couriers.map((courier) => (
                <option key={courier.id} value={courier.id}>
                  {courier.name}
                </option>
              ))}
            </select>
          </div>
        </div>

        {/* Consignee Information */}
        <div className="form-section">
          <h4>Consignee (Delivery) Information</h4>
          <div className="form-grid">
            <div className="form-group">
              <label>Name *</label>
              <input
                type="text"
                value={formData.consignee.name}
                onChange={(e) => handleConsigneeChange("name", e.target.value)}
                required
              />
            </div>
            <div className="form-group">
              <label>Phone *</label>
              <input
                type="tel"
                value={formData.consignee.phone}
                onChange={(e) => handleConsigneeChange("phone", e.target.value)}
                required
              />
            </div>
            <div className="form-group full-width">
              <label>Address Line 1 *</label>
              <input
                type="text"
                value={formData.consignee.address}
                onChange={(e) => handleConsigneeChange("address", e.target.value)}
                required
              />
            </div>
            <div className="form-group full-width">
              <label>Address Line 2</label>
              <input
                type="text"
                value={formData.consignee.address_2}
                onChange={(e) => handleConsigneeChange("address_2", e.target.value)}
              />
            </div>
            <div className="form-group">
              <label>City *</label>
              <input
                type="text"
                value={formData.consignee.city}
                onChange={(e) => handleConsigneeChange("city", e.target.value)}
                required
              />
            </div>
            <div className="form-group">
              <label>State *</label>
              <input
                type="text"
                value={formData.consignee.state}
                onChange={(e) => handleConsigneeChange("state", e.target.value)}
                required
              />
            </div>
            <div className="form-group">
              <label>Pincode *</label>
              <input
                type="text"
                value={formData.consignee.pincode}
                onChange={(e) => handleConsigneeChange("pincode", e.target.value)}
                required
              />
            </div>
          </div>
        </div>

        {/* Pickup Information */}
        <div className="form-section">
          <h4>Pickup Information</h4>
          <div className="form-grid">
            <div className="form-group">
              <label>Warehouse Name</label>
              <input
                type="text"
                value={formData.pickup.warehouse_name}
                onChange={(e) => handlePickupChange("warehouse_name", e.target.value)}
              />
            </div>
            <div className="form-group">
              <label>Contact Name *</label>
              <input
                type="text"
                value={formData.pickup.name}
                onChange={(e) => handlePickupChange("name", e.target.value)}
                required
              />
            </div>
            <div className="form-group">
              <label>Phone *</label>
              <input
                type="tel"
                value={formData.pickup.phone}
                onChange={(e) => handlePickupChange("phone", e.target.value)}
                required
              />
            </div>
            <div className="form-group full-width">
              <label>Address Line 1 *</label>
              <input
                type="text"
                value={formData.pickup.address}
                onChange={(e) => handlePickupChange("address", e.target.value)}
                required
              />
            </div>
            <div className="form-group full-width">
              <label>Address Line 2</label>
              <input
                type="text"
                value={formData.pickup.address_2}
                onChange={(e) => handlePickupChange("address_2", e.target.value)}
              />
            </div>
            <div className="form-group">
              <label>City *</label>
              <input
                type="text"
                value={formData.pickup.city}
                onChange={(e) => handlePickupChange("city", e.target.value)}
                required
              />
            </div>
            <div className="form-group">
              <label>State *</label>
              <input
                type="text"
                value={formData.pickup.state}
                onChange={(e) => handlePickupChange("state", e.target.value)}
                required
              />
            </div>
            <div className="form-group">
              <label>Pincode *</label>
              <input
                type="text"
                value={formData.pickup.pincode}
                onChange={(e) => handlePickupChange("pincode", e.target.value)}
                required
              />
            </div>
          </div>
        </div>

        {/* Products */}
        <div className="form-section">
          <div className="products-header">
            <h4>Products</h4>
            <button type="button" className="btn btn-secondary" onClick={addProduct}>
              Add Product
            </button>
          </div>
          {formData.products.map((product, index) => (
            <div key={index} className="product-item">
              <div className="form-grid">
                <div className="form-group">
                  <label>Product Name *</label>
                  <input
                    type="text"
                    value={product.product_name}
                    onChange={(e) => handleProductChange(index, "product_name", e.target.value)}
                    required
                  />
                </div>
                <div className="form-group">
                  <label>Quantity *</label>
                  <input
                    type="number"
                    value={product.product_qty}
                    onChange={(e) => handleProductChange(index, "product_qty", e.target.value)}
                    required
                  />
                </div>
                <div className="form-group">
                  <label>Price *</label>
                  <input
                    type="number"
                    step="0.01"
                    value={product.product_price}
                    onChange={(e) => handleProductChange(index, "product_price", e.target.value)}
                    required
                  />
                </div>
                {formData.products.length > 1 && (
                  <div className="form-group">
                    <label>&nbsp;</label>
                    <button
                      type="button"
                      className="btn btn-danger"
                      onClick={() => removeProduct(index)}
                    >
                      Remove
                    </button>
                  </div>
                )}
              </div>
            </div>
          ))}
        </div>

        {/* Submit Button */}
        <div className="form-actions">
          <button
            type="submit"
            className="btn btn-primary"
            disabled={loading}
          >
            {loading ? "Creating Shipment..." : "Create Shipment"}
          </button>
        </div>
      </form>
    </div>
  );
}