import http from "./utility";

// Shipping API service functions
export const shippingAPI = {
  // Get shipping dashboard stats
  getShippingStats: async () => {
    return http.get('/admin/shipping/stats');
  },

  // Create shipment
  createShipment: async (shipmentData) => {
    return http.post('/admin/shipping/create-shipment', shipmentData);
  },

  // Track shipment
  trackShipment: async (awb) => {
    return http.get(`/admin/shipping/track/${awb}`);
  },

  // Cancel shipment
  cancelShipment: async (awb) => {
    return http.post('/admin/shipping/cancel-shipment', { awb });
  },

  // Get courier list
  getCouriers: async () => {
    return http.get('/admin/shipping/couriers');
  },

  // Get NDR list
  getNDRList: async (filters = {}) => {
    return http.get('/admin/shipping/ndr', { params: filters });
  },

  // Create NDR action
  createNDRAction: async (actions) => {
    return http.post('/admin/shipping/ndr/action', { actions });
  },

  // Generate manifest
  generateManifest: async (awbs) => {
    return http.post('/admin/shipping/manifest', { awbs });
  },

  // Get serviceability
  checkServiceability: async (serviceabilityData) => {
    return http.post('/admin/shipping/serviceability', serviceabilityData);
  },

  // Get shipping login token
  getShippingToken: async () => {
    return http.post('/admin/shipping/login');
  }
};

export default shippingAPI;